let paymentOrderVnpay = (req) => {
    return new Promise(async (resolve, reject) => {
        try {
            var ipAddr =
                req.headers["x-forwarded-for"] ||
                req.connection.remoteAddress ||
                req.socket.remoteAddress ||
                req.connection.socket.remoteAddress;

            var tmnCode = process.env.VNP_TMNCODE || "2QXUI4J4";
            var secretKey = process.env.VNP_HASHSECRET || "SECRETKEY";
            var vnpUrl =
                process.env.VNP_URL ||
                "https://sandbox.vnpayment.vn/paymentv2/vpcpay.html";
            var returnUrl =
                process.env.VNP_RETURNURL ||
                `${process.env.URL_REACT || "http://localhost:3000"}/payment/vnpay_return`;

            var createDate =
                process.env.DATE_VNPAYMENT ||
                moment(new Date()).format("YYYYMMDDHHmmss");
            var orderId = uuidv4();

            var amount = req.body.amount;
            var bankCode = req.body.bankCode;

            var orderInfo = req.body.orderDescription;
            var orderType = req.body.orderType;
            var locale = req.body.language;
            if (locale === null || locale === "") {
                locale = "vn";
            }
            var currCode = "VND";
            var vnp_Params = {};
            vnp_Params["vnp_Version"] = "2.1.0";
            vnp_Params["vnp_Command"] = "pay";
            vnp_Params["vnp_TmnCode"] = tmnCode;
            vnp_Params["vnp_Locale"] = locale;
            vnp_Params["vnp_CurrCode"] = currCode;
            vnp_Params["vnp_TxnRef"] = orderId;
            vnp_Params["vnp_OrderInfo"] = orderInfo;
            vnp_Params["vnp_OrderType"] = orderType;
            vnp_Params["vnp_Amount"] = amount * 100;
            vnp_Params["vnp_ReturnUrl"] = returnUrl;
            vnp_Params["vnp_IpAddr"] = ipAddr;
            vnp_Params["vnp_CreateDate"] = createDate;
            if (bankCode !== null && bankCode !== "") {
                vnp_Params["vnp_BankCode"] = bankCode;
            }

            vnp_Params = sortObject(vnp_Params);

            var signData = querystring.stringify(vnp_Params, { encode: false });

            var hmac = crypto.createHmac("sha512", secretKey);
            var signed = hmac
                .update(new Buffer(signData, "utf-8"))
                .digest("hex");
            vnp_Params["vnp_SecureHash"] = signed;

            vnpUrl +=
                "?" + querystring.stringify(vnp_Params, { encode: false });
            resolve({
                errCode: 200,
                link: vnpUrl,
            });
        } catch (error) {
            reject(error);
        }
    });
};

let confirmOrderVnpay = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            var vnp_Params = data;

            var secureHash = vnp_Params["vnp_SecureHash"];

            delete vnp_Params["vnp_SecureHash"];
            delete vnp_Params["vnp_SecureHashType"];

            vnp_Params = sortObject(vnp_Params);

            var tmnCode = process.env.VNP_TMNCODE || "2QXUI4J4";
            var secretKey = process.env.VNP_HASHSECRET || "SECRETKEY";

            var signData = querystring.stringify(vnp_Params, { encode: false });

            var hmac = crypto.createHmac("sha512", secretKey);
            var signed = hmac
                .update(new Buffer(signData, "utf-8"))
                .digest("hex");

            if (secureHash === signed) {
                resolve({
                    errCode: 0,
                    errMessage: "Success",
                });
            } else {
                resolve({
                    errCode: 1,
                    errMessage: "failed",
                });
            }
        } catch (error) {
            reject(error);
        }
    });
};

function sortObject(obj) {
    var sorted = {};
    var str = [];
    var key;
    for (key in obj) {
        if (obj.hasOwnProperty(key)) {
            str.push(encodeURIComponent(key));
        }
    }
    str.sort();
    for (key = 0; key < str.length; key++) {
        sorted[str[key]] = encodeURIComponent(obj[str[key]]).replace(
            /%20/g,
            "+"
        );
    }
    return sorted;
}

let updateImageOrder = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.id || !data.image) {
                resolve({
                    errCode: 1,
                    errMessage: "Missing required parameter !",
                });
            } else {
                let order = await db.OrderProduct.findOne({
                    where: { id: data.id },
                    raw: false,
                });
                order.image = data.image;
                await order.save();

                resolve({
                    errCode: 0,
                    errMessage: "ok",
                });
            }
        } catch (error) {
            reject(error);
        }
    });
};

module.exports = {
